syntax.tsql:
SELECT key, [A], [B]
FROM (SELECT key, cat, val FROM t) AS src
PIVOT (SUM(val) FOR cat IN ([A], [B])) AS p;

syntax.mysql:
SET @sql = CONCAT('SELECT sale_date, ', @cols, ' FROM daily_sales GROUP BY sale_date');
PREPARE stmt FROM @sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

examples.mysql:
SELECT GROUP_CONCAT(frag ORDER BY frag SEPARATOR ', ') AS pivot_cols
FROM (SELECT DISTINCT CONCAT('SUM(CASE WHEN region = ''', region, ''' THEN revenue END) AS ', region) AS frag
      FROM daily_sales) AS f;

examples.tsql:
SELECT STRING_AGG(frag, ', ') WITHIN GROUP (ORDER BY frag) AS pivot_cols
FROM (SELECT DISTINCT 'SUM(CASE WHEN region = ''' + region + ''' THEN revenue END) AS ' + region AS frag
      FROM daily_sales) AS f;
